import{z as l,x as A,o as t,c as d,q as n,j as B,D as e,d as r,s,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"研究代码的规范","description":"","frontmatter":{"title":"研究代码的规范","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc2-code-standards.md","filePath":"quant/rc2-code-standards.md","lastUpdated":1791413859000}'),C={name:"quant/rc2-code-standards.md"};function p(f,a,D,m,u,c){const o=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=n('<h1 id="研究代码的规范" tabindex="-1">研究代码的规范 <a class="header-anchor" href="#研究代码的规范" aria-label="Permalink to &quot;研究代码的规范&quot;">​</a></h1><div class="epigraph"><p>研究代码的第一位用户不是同事，是三个月后的自己；规范的全部内容，是让那时的他还能重跑今天这一行。</p><footer>—— 据 Wilson et al., Best Practices for Scientific Computing, 2014；Sandve et al., Ten Simple Rules for Reproducible Computational Research, PLoS Computational Biology, 2013 整理</footer></div><p><a href="/quant/bf-opensource-map">上一课</a>按七个器官对照四个开源谱系，把「自建还是采用」分了账，回测框架设计课程收束——框架把回测语义做成可维护、可审计、可重放的软件。可重放的引擎只是复现的一半；另一半住在写策略的人手里：同一台引擎，喂进两段写得随意的策略代码，结果照样对不上。本课程写研究协作与复现，先从个人层的代码规范起步。本单元四课依次是规范、notebook、实验管理与复现包；组织层的评审、文档、知识库、委员会与跨团队契约都在它们之后。后课默认已经按本课的方式写代码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>研究代码的目标函数与生产代码不同。生产代码追求长期演化的可维护；研究代码要两件相反的事同时成立——今天改得快，三个月后跑得同。只顾前者，第三天就出现「当时是哪组参数跑出了这张图」的考古现场；只顾后者，事事按生产标准上抽象上框架，探索速度被拖死，研究退化成工程。缺口不是一套风格指南，而是一条最小约束：<strong>重跑所需的每样东西都必须显式</strong>。凡是隐含的——路径、种子、依赖版本、当日手动改过的区间——都会在重跑时变成一次静默的改题。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="五条最小规范" tabindex="-1">五条最小规范 <a class="header-anchor" href="#五条最小规范" aria-label="Permalink to &quot;五条最小规范&quot;">​</a></h3><p><strong>配置与代码分离</strong>：会变的数——参数、路径、日期区间、universe 定义——进一份配置文件，代码只读不写。改参即改配置，代码不 diff；<a href="/quant/bf-param-sweep-arch">参数扫描的架构</a>的落库口径照用。<strong>计算核与 IO 边界分离</strong>：加载与清洗在外层，计算核写成纯函数，输入矩阵与配置、输出结果，不读文件、不读墙钟。<strong>显式种子</strong>：随机源统一从配置取种子，每次运行一个生成器，不用全局默认态。<strong>依赖锁定</strong>：环境清单钉死版本，与代码同库提交。<strong>单一入口</strong>：一条命令从数据快照跑到结果表，中间没有「先手动跑一下」。</p>',8)),(t(),B(i,null,{default:e(()=>[s(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22%E9%85%8D%E7%BD%AE%E6%96%87%E4%BB%B6%20%E5%8F%82%E6%95%B0%20%E8%B7%AF%E5%BE%84%20%E5%8C%BA%E9%97%B4%22%5D%20--%3E%20CORE%5B%22%E7%BA%AF%E5%87%BD%E6%95%B0%E8%AE%A1%E7%AE%97%E6%A0%B8%22%5D%0A%20%20SEED%5B%22%E6%98%BE%E5%BC%8F%E7%A7%8D%E5%AD%90%22%5D%20--%3E%20CORE%0A%20%20LOCK%5B%22%E4%BE%9D%E8%B5%96%E9%94%81%20%2B%20%E6%95%B0%E6%8D%AE%E7%89%88%E6%9C%AC%E5%BC%95%E7%94%A8%22%5D%20--%3E%20IO%5B%22%E5%A4%96%E5%B1%82%EF%BC%9A%E5%8A%A0%E8%BD%BD%E4%B8%8E%E6%B8%85%E6%B4%97%22%5D%0A%20%20IO%20--%3E%20CORE%0A%20%20CORE%20--%3E%20OUT%5B%22%E7%BB%93%E6%9E%9C%E8%A1%A8%20%2B%20%E8%BF%90%E8%A1%8C%E8%AE%B0%E5%BD%95%22%5D%0A%20%20OUT%20--%3E%20RERUN%5B%22%E4%B8%89%E4%B8%AA%E6%9C%88%E5%90%8E%E5%90%8C%E5%91%BD%E4%BB%A4%E9%87%8D%E8%B7%91%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"Sandve 等十条规则的第一条：除非把结果的全部依赖记录下来，否则不要宣称任何一个结果。五条规范是这条规则的最小实现——缺任何一条，就有一项依赖仍处在隐含状态，等着在重跑时改题。")],-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"数字实例看「显式种子」：同一策略含随机入场，今天跑年化 12.3%，明天同一份代码跑出 14.1%——因为 numpy 用了全局默认随机态，每次开进程抽到的序列都不同。把种子写进配置（如 seed=42）后，每次运行生成同一串随机数，两次重跑的差异就只剩你真正改过的那几行。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"这五条把一次实验从「动作」变成可复述的函数：\\(f(\\text{配置}, \\text{数据快照}) \\to \\text{结果}\\)。可复述才可归因：两次结果的差异要么来自配置 diff，要么来自数据版本 diff，不会来自「我记得那天顺手改了点什么」。归因不清，横比就失效：台账横向比较的可行性，正建立在每次运行的输入都被钉住之上。",-1)),(t(),B(i,null,{default:e(()=>[s(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%B8%A4%E6%AC%A1%E9%87%8D%E8%B7%91%E7%BB%93%E6%9E%9C%E4%B8%8D%E4%B8%80%E8%87%B4%22%5D%20--%3E%20B%7B%22%E9%85%8D%E7%BD%AE%E6%96%87%E4%BB%B6%E6%9C%89%20diff%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E6%9C%89%22%7C%20C%5B%22%E5%BD%92%E5%9B%A0%EF%BC%9A%E5%8F%82%E6%95%B0%E6%94%B9%E5%8A%A8%E6%89%80%E8%87%B4%22%5D%0A%20%20B%20--%3E%7C%22%E6%97%A0%22%7C%20D%7B%22%E6%95%B0%E6%8D%AE%E5%BF%AB%E7%85%A7%E7%89%88%E6%9C%AC%E4%B8%8D%E5%90%8C%EF%BC%9F%22%7D%0A%20%20D%20--%3E%7C%22%E6%9C%89%22%7C%20E%5B%22%E5%BD%92%E5%9B%A0%EF%BC%9A%E6%95%B0%E6%8D%AE%E7%89%88%E6%9C%AC%E6%94%B9%E5%8A%A8%E6%89%80%E8%87%B4%22%5D%0A%20%20D%20--%3E%7C%22%E6%97%A0%22%7C%20F%5B%22%E6%80%80%E7%96%91%E9%9A%90%E5%90%AB%E4%BE%9D%E8%B5%96%22%5D%0A%20%20F%20--%3E%20G%5B%22%E7%A1%AC%E7%BC%96%E7%A0%81%E8%B7%AF%E5%BE%84%20%2F%20%E5%85%A8%E5%B1%80%E9%9A%8F%E6%9C%BA%E6%80%81%20%2F%20%E6%9C%AA%E9%94%81%E7%89%88%E6%9C%AC%22%5D%0A%20%20G%20--%3E%20H%5B%22%E8%A1%A5%E9%BD%90%E5%AF%B9%E5%BA%94%E8%A7%84%E8%8C%83%E5%90%8E%E9%87%8D%E8%B7%91%E9%AA%8C%E8%AF%81%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">术语翻译：「纯函数」就是不偷看墙钟、不偷改文件的函数——同样的输入永远给出同样的输出，像计算器而不是温度计。计算核写成纯函数后，「结果为什么变了」只剩两个可能的来源：配置或数据，排查从考古变成做一次 diff。</span></p><p>不这么做错在哪，各有一条典型死法。硬编码的绝对路径把实验绑在某台机器上，换机即哑；未声明的随机源让两次「同一实验」的年化收益在小数点后第二位分叉，你会开始把噪声读成信号；依赖不锁，同事装出的环境里某个库升了一版，结果差异比策略改进还大。代码钉住依赖，数据侧的对应物是<a href="/quant/de-data-versioning">数据版本化</a>的版本引用：实验钉三要素——定义、数据版本、清洗规则——与特征存储同构。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>这套规范不解决正确性：写得再规范，仍可能有未来函数与幸存者偏差，那是协作单元评审清单的事。它也不要求测试覆盖率与抽象层级——研究代码允许丑，不允许不可重跑；为三个月寿命的脚本上工厂级的分层，是把规范读成了教条。探索期的草稿可以不达标，但草稿一旦被引用——进了文档、进了汇报、进了台账——就必须先补齐五条：被引用的结果没有豁免权。notebook 不是豁免区，只是另一套执行环境，下一课写它的纪律。</p><p><span class="marginnote">常见误区：初学者容易以为规范是为了「代码好看」，于是能省则省。实际上它买的是归因能力——依赖锁定就像做菜把「盐少许」改成「盐 3 克」：不写死，三个月后没有人（包括你自己）能复刻出同一锅汤。省下的三十秒，会在第一次「结果对不上」时连本带利还回去。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>研究代码的目标是「今天改得快、三个月后跑得同」，规范只约束重跑所需之物的显式性。</li><li>五条最小规范：配置分离、计算核与 IO 边界分离、显式种子、依赖锁定、单一入口。</li><li>规范把实验变成 \\(f(\\text{配置}, \\text{快照}) \\to \\text{结果}\\)，差异可归因于配置或数据版本的 diff。</li><li>被引用的草稿没有豁免权：进了文档、台账或汇报，先补齐五条。</li><li>出处：Wilson et al., <em>Best Practices for Scientific Computing</em>, 2014；Sandve et al., <em>PLoS Comput Biol</em>, 2013；站内<a href="/quant/bf-param-sweep-arch">参数扫描的架构</a>、<a href="/quant/de-data-versioning">数据版本化</a>各课。</li></ul>',7))])}const b=l(C,[["render",p]]);export{g as __pageData,b as default};
